"""Intent tests for risk.summary_stats (RISK-04, TC-07): annualized return, volatility, Sharpe, last vol."""

from __future__ import annotations

import math

import pytest

from risk.summary import TickerSummary, summary_stats
from risk.types import Returns, VolSeries


def _returns_from(payload: dict) -> Returns:
    return Returns(
        base_date=payload["base_date"],
        dates=tuple(payload["dates"]),
        tickers=tuple(payload["tickers"]),
        values={ticker: tuple(series) for ticker, series in payload["values"].items()},
    )


def _vol_from(payload: dict) -> VolSeries:
    return VolSeries(
        returns=_returns_from(payload["returns"]),
        window=payload["window"],
        annualized=payload["annualized"],
        values={ticker: tuple(series) for ticker, series in payload["values"].items()},
    )


def _assert_close(got: float | None, want: float | None, tol: float) -> None:
    if want is None:
        assert got is None
    else:
        assert got == pytest.approx(want, abs=tol, rel=0)


@pytest.mark.intent
def test_tc07_one_summary_per_ticker_in_ticker_order(golden) -> None:
    given, expected = golden("risk", "TC-07")
    summaries = summary_stats(_vol_from(given["vol"]))
    assert isinstance(summaries, tuple)
    assert all(isinstance(summary, TickerSummary) for summary in summaries)
    assert [s.ticker for s in summaries] == [row["ticker"] for row in expected["summary"]]


@pytest.mark.intent
def test_tc07_annualized_return_vol_sharpe_and_last_vol(golden) -> None:
    given, expected = golden("risk", "TC-07")
    tol = expected["tol"]
    by_ticker = {s.ticker: s for s in summary_stats(_vol_from(given["vol"]))}
    for row in expected["summary"]:
        got = by_ticker[row["ticker"]]
        _assert_close(got.ann_return, row["ann_return"], tol)
        _assert_close(got.ann_vol, row["ann_vol"], tol)
        _assert_close(got.sharpe, row["sharpe"], tol)
        _assert_close(got.last_vol, row["last_vol"], tol)


@pytest.mark.intent
def test_tc07_zero_volatility_gives_zero_sharpe(golden) -> None:
    given, expected = golden("risk", "TC-07")
    tol = expected["tol"]
    flat = [row for row in expected["summary"] if row["ann_vol"] == 0.0]
    assert flat
    by_ticker = {s.ticker: s for s in summary_stats(_vol_from(given["vol"]))}
    for row in flat:
        got = by_ticker[row["ticker"]]
        assert got.ann_vol == pytest.approx(0.0, abs=tol, rel=0)
        assert got.sharpe == 0.0
        assert math.isfinite(got.sharpe)


@pytest.mark.intent
def test_tc07_default_periods_per_year_is_252(golden) -> None:
    given, expected = golden("risk", "TC-07")
    tol = expected["tol"]
    vol = _vol_from(given["vol"])
    default = summary_stats(vol)
    explicit = summary_stats(vol, periods_per_year=252)
    for got, want in zip(default, explicit, strict=True):
        assert got.ticker == want.ticker
        _assert_close(got.ann_return, want.ann_return, tol)
        _assert_close(got.ann_vol, want.ann_vol, tol)
        _assert_close(got.sharpe, want.sharpe, tol)
    for got, row in zip(default, expected["summary"], strict=True):
        _assert_close(got.ann_return, row["ann_return"], tol)


@pytest.mark.intent
def test_periods_per_year_scales_return_linearly_and_vol_by_its_root(golden) -> None:
    given, expected = golden("risk", "TC-07")
    tol = expected["tol"]
    periods = 12
    by_ticker = {s.ticker: s for s in summary_stats(_vol_from(given["vol"]), periods_per_year=periods)}
    for row in expected["summary"]:
        got = by_ticker[row["ticker"]]
        want_return = row["ann_return"] * periods / 252
        want_vol = row["ann_vol"] * math.sqrt(periods / 252)
        _assert_close(got.ann_return, want_return, tol)
        _assert_close(got.ann_vol, want_vol, tol)
        want_sharpe = want_return / want_vol if want_vol else 0.0
        _assert_close(got.sharpe, want_sharpe, tol)


@pytest.mark.intent
def test_fewer_than_two_returns_is_a_value_error(contract_sample) -> None:
    payload = contract_sample("risk.VolSeries")
    one_date = payload["returns"]["dates"][:1]
    short = {
        "returns": {
            **payload["returns"],
            "dates": one_date,
            "values": {t: s[:1] for t, s in payload["returns"]["values"].items()},
        },
        "window": payload["window"],
        "annualized": payload["annualized"],
        "values": {t: s[:1] for t, s in payload["values"].items()},
    }
    with pytest.raises(ValueError, match="two returns"):
        summary_stats(_vol_from(short))

